function build(api) {
  api.name('皮卡丘');
  const C_Y = 0xFFCC00, C_YD = 0xE6B800, C_BR = 0x8B4513, C_RD = 0xFF3333, C_BK = 0x111111;

  api.group('body', '躯干');
    api.group('chest', '胸');
      api.sphere({r: 1.2, pos: [0, 2.2, 0], color: C_Y});
    api.endGroup();
    api.group('abdomen', '腹');
      api.sphere({r: 1.1, pos: [0, 1.0, 0], color: C_Y});
    api.endGroup();
    api.group('pelvis', '胯');
      api.sphere({r: 0.9, pos: [0, 0.2, 0], color: C_Y});
    api.endGroup();
    api.box({w: 0.6, h: 1.8, d: 0.08, pos: [0, 1.8, -1.15], color: C_BR});
    api.box({w: 0.6, h: 1.8, d: 0.08, pos: [0, 1.8, -1.05], color: C_BR});
  api.endGroup();

  api.group('head', '头');
    api.sphere({r: 1.1, pos: [0, 3.8, 0.2], color: C_Y});
    api.sphere({r: 0.6, pos: [0, 3.2, 0.9], color: C_Y});

    api.group('leftEar', '左耳');
      api.chain({waypoints: [[-0.5, 4.6, 0.2], [-0.7, 5.8, -0.2], [-0.9, 6.8, -0.5]], r: 0.2, rEnd: 0.08, jointIds: ['earBase', 'earMid', 'earTip'], color: C_Y});
      api.cone({r: 0.12, h: 0.4, along: '-Y+X-Z', pos: [-0.9, 7.0, -0.5], color: C_BK});
    api.endGroup();

    api.group('rightEar', '右耳');
      api.chain({waypoints: [[0.5, 4.6, 0.2], [0.7, 5.8, -0.2], [0.9, 6.8, -0.5]], r: 0.2, rEnd: 0.08, jointIds: ['earBase', 'earMid', 'earTip'], color: C_Y});
      api.cone({r: 0.12, h: 0.4, along: '-Y-X-Z', pos: [0.9, 7.0, -0.5], color: C_BK});
    api.endGroup();

    api.poly({r: 0.25, pos: [-0.45, 3.7, 1.2], color: C_BK});
    api.poly({r: 0.25, pos: [0.45, 3.7, 1.2], color: C_BK});
    api.sphere({r: 0.35, pos: [-0.75, 3.3, 0.8], color: C_RD});
    api.sphere({r: 0.35, pos: [0.75, 3.3, 0.8], color: C_RD});
    api.box({w: 0.15, h: 0.08, d: 0.08, pos: [-0.45, 3.55, 1.25], color: 0xFFFFFF});
    api.box({w: 0.15, h: 0.08, d: 0.08, pos: [0.45, 3.55, 1.25], color: 0xFFFFFF});
  api.endGroup();

  api.mirror('x');
  api.group('leftArm', '左臂');
    api.chain({waypoints: [[-1.2, 2.2, 0], [-1.5, 1.5, 0.3], [-1.4, 0.8, 0.5]], r: 0.2, rEnd: 0.15, jointIds: ['shoulder', 'elbow', 'hand'], color: C_Y});
  api.endGroup();
  api.endMirror();

  api.mirror('x');
  api.group('leftLeg', '左腿');
    api.chain({waypoints: [[-0.5, 0.2, 0], [-0.6, -0.5, 0.2], [-0.5, -1.0, 0.5]], r: 0.25, rEnd: 0.3, jointIds: ['hip', 'knee', 'foot'], color: C_Y});
  api.endGroup();
  api.endMirror();

  api.group('tail', '尾巴');
    api.chain({waypoints: [[0, 1.5, -1.2], [0, 2.5, -2.0], [0, 2.0, -2.8], [0, 3.0, -3.5], [0, 2.5, -4.2]], r: 0.2, rEnd: 0.15, jointIds: ['tailBase', 'zig1', 'zag1', 'zig2', 'tailTip'], color: C_Y});
    api.cone({r: 0.2, h: 0.5, along: '+Z-Y', pos: [0, 2.3, -1.2], color: C_BR});
  api.endGroup();
}
